Here is the commit message:
xprtrdma: Fix cwnd update ordering

After a reconnect, the reply handler is opening the cwnd (and thus
enabling more RPC Calls to be sent) /before/ rpcrdma_post_recvs()
can post enough Receive WRs to receive their replies. This causes an
RNR and the new connection is lost immediately.

The race is most clearly exposed when KASAN and disconnect injection
are enabled. This slows down rpcrdma_rep_create() enough to allow
the send side to post a bunch of RPC Calls before the Receive
completion handler can invoke ib_post_recv().

Fixes: 2ae50ad68cd7 ("xprtrdma: Close window between waking RPC senders and posting Receives")
Signed-off-by: Chuck Lever <chuck.lever@oracle.com>
Signed-off-by: Trond Myklebust <trond.myklebust@hammerspace.com>

Here is the root cause:
The bug is caused by the reply handler opening the congestion window (cwnd) and allowing more RPC calls to be sent before sufficient receive work requests (WRs) are posted to handle incoming replies. This leads to a situation where the sender can overwhelm the receiver, resulting in a "Receive Not Ready" (RNR) condition and causing the new connection to fail immediately. The race condition is exacerbated when certain debugging features are enabled, which slow down the posting of receive buffers.

Here is the patch:
  */
 void rpcrdma_reply_handler(struct rpcrdma_rep *rep)
 {
 	struct rpcrdma_xprt *r_xprt = rep->rr_rxprt;
 	struct rpc_xprt *xprt = &r_xprt->rx_xprt;
 	struct rpcrdma_buffer *buf = &r_xprt->rx_buf;
 	struct rpcrdma_req *req;
 	struct rpc_rqst *rqst;
 	u32 credits;
 	__be32 *p;

 	/* Any data means we had a useful conversation, so
 	 * then we don't need to delay the next reconnect.
 	 */
 	if (xprt->reestablish_timeout)
 		xprt->reestablish_timeout = 0;

 	/* Fixed transport header fields */
 	xdr_init_decode(&rep->rr_stream, &rep->rr_hdrbuf,
 			rep->rr_hdrbuf.head[0].iov_base, NULL);
 	p = xdr_inline_decode(&rep->rr_stream, 4 * sizeof(*p));
 	if (unlikely(!p))
 		goto out_shortreply;
 	rep->rr_xid = *p++;
 	rep->rr_vers = *p++;
 	credits = be32_to_cpu(*p++);
 	rep->rr_proc = *p++;

 	if (rep->rr_vers != rpcrdma_version)
 		goto out_badversion;

 	if (rpcrdma_is_bcall(r_xprt, rep))
 		return;

 	/* Match incoming rpcrdma_rep to an rpcrdma_req to
 	 * get context for handling any incoming chunks.
 	 */
 	spin_lock(&xprt->queue_lock);
 	rqst = xprt_lookup_rqst(xprt, rep->rr_xid);
 	if (!rqst)
 		goto out_norqst;
 	xprt_pin_rqst(rqst);
 	spin_unlock(&xprt->queue_lock);

 	if (credits == 0)
 		credits = 1;	/* don't deadlock */
 	else if (credits > r_xprt->rx_ep->re_max_requests)
 		credits = r_xprt->rx_ep->re_max_requests;
+	rpcrdma_post_recvs(r_xprt, credits + (buf->rb_bc_srv_max_requests << 1),
+			   false);
 	if (buf->rb_credits != credits)
 		rpcrdma_update_cwnd(r_xprt, credits);
-	rpcrdma_post_recvs(r_xprt, false);

 	req = rpcr_to_rdmar(rqst);
 	if (unlikely(req->rl_reply))
 		rpcrdma_recv_buffer_put(req->rl_reply);
 	req->rl_reply = rep;
 	rep->rr_rqst = rqst;

 	trace_xprtrdma_reply(rqst->rq_task, rep, credits);

 	if (rep->rr_wc_flags & IB_WC_WITH_INVALIDATE)
 		frwr_reminv(rep, &req->rl_registered);
 	if (!list_empty(&req->rl_registered))
 		frwr_unmap_async(r_xprt, req);
 		/* LocalInv completion will complete the RPC */
 	else
 		kref_put(&req->rl_kref, rpcrdma_reply_done);
 	return;

 out_badversion:
 	trace_xprtrdma_reply_vers_err(rep);
 	goto out;

 out_norqst:
 	spin_unlock(&xprt->queue_lock);
 	trace_xprtrdma_reply_rqst_err(rep);
 	goto out;

 out_shortreply:
 	trace_xprtrdma_reply_short_err(rep);

 out:
 	rpcrdma_recv_buffer_put(rep);
 }


